insert into imhcc.site_settings (id, company_name, tagline, hero_title, hero_subtitle, phone_primary, phone_secondary, email, address, business_hours, facebook_url, messenger_url, map_embed_url, latitude, longitude, about_intro, mission, vision, stats) values (1, 'Iloilo Modern Homes Construction Co.', 'Live in the very best home where your family can nurture and grow in safety. Construct with us!', 'Building your dreams, creating spaces that last.', 'From residential construction to modern renovations and modular kitchens, Iloilo Modern Homes brings your vision to life with quality workmanship and dependable service.', '0917 384 3099', null, null, 'Santa Barbara, Iloilo, Philippines', 'Monday to Saturday, 8:00 AM to 5:00 PM', 'https://www.facebook.com/iloilomodernhomesconstructionco', 'https://m.me/iloilomodernhomesconstructionco?ref=website', null, 10.8231, 122.5337, 'Iloilo Modern Homes Construction Co. is a construction, renovation, and hardware supply business based in Santa Barbara, Iloilo. We serve homeowners and businesses across Iloilo City and Iloilo Province, from new builds to kitchen makeovers and complete interior fit-outs.', 'To build safe, beautiful, and lasting spaces for Ilonggo families and businesses through honest pricing, skilled workmanship, and clear communication from first visit to handover.', 'To be the most trusted construction partner in Iloilo, known for modern design, quality results, and customers who recommend us to their families.', '[{"value":"Free","label":"Site visit and quotation"},{"value":"Iloilo-wide","label":"City and province coverage"},{"value":"One team","label":"Design, build, and supply"},{"value":"Real work","label":"Every photo is our own project"}]'::jsonb) on conflict (id) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('modular-kitchens-cabinets', 'Modular kitchens and cabinets', 'Interior', 'Custom cabinets, islands, and countertops built to fit your space.', 'We design and install modular kitchen cabinets, breakfast islands, pantry units, and countertops in laminate, solid surface, or marble finishes. Every unit is measured on site so it fits your space and your daily routine.', array['Base and wall cabinets', 'Kitchen islands and peninsulas', 'Countertops and backsplash', 'Under-cabinet and pendant lighting']::text[], '/images/projects/kitchen-island-pendants.jpg', 1, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('interior-fit-outs', 'Interior fit-outs', 'Interior', 'TV feature walls, built-ins, wall panels, and finishing works.', 'Turn a bare unit or room into a finished, livable space. We build TV feature walls, wardrobes, study desks, wall cladding, and room partitions for homes, condos, and offices.', array['TV and feature walls', 'Wardrobes and built-ins', 'Fluted and PVC wall panels', 'Condo and office fit-outs']::text[], '/images/projects/tv-wall-aurora.jpg', 2, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('ceilings-and-lighting', 'Ceilings and lighting', 'Interior', 'Gypsum and wood ceilings with cove and accent lighting.', 'Drop ceilings, cove lighting, wood slat ceilings, and lighting layouts that make a room feel finished. We handle framing, boarding, finishing, and the electrical work behind it.', array['Gypsum board ceilings', 'Cove and LED strip lighting', 'Wood and PVC slat ceilings', 'Lighting layout and installation']::text[], '/images/projects/bedroom-cove-ceiling.jpg', 3, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('bathroom-renovation', 'Bathroom renovation', 'Renovation', 'Tiling, fixtures, plumbing, and complete bathroom makeovers.', 'From a simple fixture upgrade to a full marble bathroom, we handle demolition, waterproofing, plumbing, tiling, vanities, and lighting.', array['Waterproofing and tiling', 'Vanities and mirrors', 'Plumbing and fixtures', 'Shower and tub installation']::text[], '/images/projects/bathroom-round-mirror.jpg', 4, true, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('residential-construction', 'Residential construction', 'Construction', 'New houses built from foundation to finishing.', 'We build new homes from foundation to turnover, coordinating structural, electrical, plumbing, roofing, and finishing works under one team.', array['Foundation and structural works', 'Masonry and concrete', 'Roofing', 'Finishing and turnover']::text[], '/images/projects/loft-bedroom.jpg', 5, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('commercial-construction', 'Commercial construction', 'Construction', 'Stores, offices, and rental units built for business.', 'Construction and renovation of shops, offices, and rental spaces, planned to minimize downtime for your business.', array['Store and office fit-outs', 'Rental unit construction', 'Renovation and repair']::text[], '/images/projects/studio-pendant-lights.jpg', 6, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('renovation', 'General renovation', 'Renovation', 'Updates and repairs for older homes and spaces.', 'Whole-house or room-by-room renovation, including layout changes, repairs, and modern finishes.', array['Layout changes', 'Repairs and restoration', 'Modern finishes']::text[], '/images/projects/white-kitchen-wood-ceiling.jpg', 7, false, true) on conflict (slug) do nothing;
insert into imhcc.services (slug, name, category, summary, description, scope, cover_image, sort_order, is_featured, is_published) values ('electrical-and-plumbing', 'Electrical and plumbing', 'Technical', 'Safe wiring, lighting, water lines, and drainage.', 'Electrical wiring, panel upgrades, lighting, water supply lines, and drainage, done to code by experienced workers.', array['Wiring and panel upgrades', 'Lighting installation', 'Water lines and drainage']::text[], '/images/projects/kitchen-teal-cove.jpg', 8, false, true) on conflict (slug) do nothing;
